import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";

import Login from "./components/login";
import BankUpload from "./components/BankUpload";
import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";

function AppRouter() {
  const [bankData, setBankData] = useState([]);

  const [formData, setFormData] = useState({
    incomeType: "",
    category: "",
    questionnaire: {},
    spendingPriority: {},
    budgetLimits: {},
  });

  const handleIncomeNext = (incomeType) => {
    setFormData(prev => ({
      ...prev,
      incomeType: incomeType,
      category: incomeType
    }));
  };

  const handleQuestionnaireNext = (data) => {
    setFormData(prev => ({ ...prev, questionnaire: data }));
  };

  const handleSpendingNext = (data) => {
    setFormData(prev => ({ ...prev, spendingPriority: data }));
  };

  const handleSave = async (limits) => {
    const finalData = {
      incomeType: formData.incomeType || "No Income",
      category: formData.category || "No Income",
      questionnaire: formData.questionnaire,
      spendingPriority: formData.spendingPriority,
      budgetLimits: limits,
    };

    try {
      const res = await fetch("http://localhost:5000/api/userdata/save", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(finalData),
      });

      const data = await res.json();
      if (data.success) alert("Limits saved successfully!");
      else alert("Error saving data");
    } catch (err) {
      console.error(err);
      alert("Server connection failed");
    }
  };

  return (
    <Router>
      <Routes>

        {/* START DIRECTLY FROM INCOME PAGE */}
        <Route path="/" element={<Navigate to="/income" />} />

        <Route
          path="/income"
          element={<IncomeCategory onNext={handleIncomeNext} />}
        />

        <Route
          path="/questionnaire"
          element={<Questionnaire onNext={handleQuestionnaireNext} />}
        />

        <Route
          path="/spending"
          element={<SpendingPriority onNext={handleSpendingNext} />}
        />

        <Route
          path="/budget"
          element={
            <BudgetLimits
              categories={Object.keys(formData.spendingPriority).filter(
                cat => formData.spendingPriority[cat] >= 3
              )}
              onSave={handleSave}
            />
          }
        />

        {/* Optional: still keep bank upload if needed */}
        <Route
          path="/upload"
          element={<BankUpload onUpload={setBankData} />}
        />

        {/* Login page kept but NOT default */}
        <Route path="/login" element={<Login />} />

      </Routes>
    </Router>
  );
}

export default AppRouter;
